INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m6-004', 'c1-m6-i4', 'calculus-1', 'c1-m6', 0, '变力做功', '一物体在变力 \\( F(x)=2x \\) 作用下沿直线从 \\( x=0 \\) 移动到 \\( x=3 \\)，求力所做的功。', '["8","18","9","10"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( W=\\int_0^3 2x\\,dx=9 \\)。', NULL, NULL, NULL, 2, '["物理应用"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m6-005', 'c1-m6-i5', 'calculus-1', 'c1-m6', 0, '小测：面积元素', '由 \\( y=f(x)\\ge0 \\)、\\( x=a \\)、\\( x=b \\) 与 \\( x \\) 轴围成的曲边梯形面积为（ ）', '["\\\\( \\\\displaystyle\\\\int_a^b f(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_a^b f^{\\\\prime}(x)\\\\,dx \\\\)","\\\\( \\\\displaystyle\\\\int_b^a f(x)\\\\,dx \\\\)","\\\\( f(b)-f(a) \\\\)"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '面积为 \\( \\int_a^b f(x)\\,dx \\)。', NULL, NULL, NULL, 2, '["面积"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-001', 'c1-m7-i1', 'calculus-1', 'c1-m7', 0, '微分方程阶数', '方程 \\( y^{\\prime\\prime}+3y^{\\prime}+2y=0 \\) 的阶数为 __________。', '["4","3","2","1"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '最高阶导数为二阶。', NULL, NULL, NULL, 2, '["微分方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-002', 'c1-m7-i2', 'calculus-1', 'c1-m7', 0, '可分离变量', '求微分方程 \\( \\frac{dy}{dx}=xy \\) 满足 \\( y(0)=1 \\) 的特解。', '["e^{x^2/2}","e^{x^2/2}-1","选项1","e^{x^2/2}+1"]'::jsonb, '0', '[]'::jsonb, NULL, NULL, NULL, '分离变量并积分：\\( \\ln|y|=\\frac{x^2}{2}+C \\)，由初值得 \\( y=e^{x^2/2} \\)。', NULL, NULL, NULL, 2, '["微分方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-003', 'c1-m7-i3', 'calculus-1', 'c1-m7', 0, '一阶线性方程', '求微分方程 \\( y^{\\prime}+y=e^x \\) 的通解。', '["Ce^{-x}+0.5e^x+1","Ce^{-x}+0.5e^x-1","Ce^{-x}+0.5e^x","Ce^{-x}-0.5e^x"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '积分因子 \\( e^x \\)，得 \\( (ye^x)^{\\prime}=e^{2x} \\)，\\( y=\\frac12 e^x+C e^{-x} \\)。', NULL, NULL, NULL, 2, '["微分方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-004', 'c1-m7-i4', 'calculus-1', 'c1-m7', 0, '二阶常系数齐次方程', '求微分方程 \\( y^{\\prime\\prime}-5y^{\\prime}+6y=0 \\) 的通解。', '["C_1e^{2x}_2e^{3x}","C_1e^{2x}+C_2e^{3x}","C_1e^{2x}-C_2e^{3x}","C_1e^{2x}+1_2e^{3x}"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '特征方程 \\( r^2-5r+6=0 \\)，根 \\( r=2,3 \\)。', NULL, NULL, NULL, 2, '["微分方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-005', 'c1-m7-i5', 'calculus-1', 'c1-m7', 0, '微分方程综合', '求微分方程 \\( y^{\\prime}=2x(1+y^2) \\) 的通解。', '["arctany=0","arctany=x^2+C","arctany=1","arctany=-1"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '分离变量：\\( \\frac{dy}{1+y^2}=2x\\,dx \\)，积分得 \\( \\arctan y=x^2+C \\)。', NULL, NULL, NULL, 2, '["微分方程"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-006', 'c1-m7-i6', 'calculus-1', 'c1-m7', 0, '人口增长模型', '简述马尔萨斯人口模型 \\( \\frac{dP}{dt}=kP \\) 的解及其现实意义。', '["P=1","P=P_0e^{kt}","P=-1","P=0"]'::jsonb, '1', '[]'::jsonb, NULL, NULL, NULL, '分离变量得指数增长模型 \\( P=P_0e^{kt} \\)，反映资源无限时人口按指数增长。', NULL, NULL, NULL, 2, '["应用"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-calculus-1-c1-m7-007', 'c1-m7-i7', 'calculus-1', 'c1-m7', 0, '总复习：核心概念', '下列等式正确的是（ ）', '["\\\\( \\\\frac{d}{dx}\\\\int f(x)\\\\,dx=f(x)+C \\\\)","\\\\( \\\\int f^{\\\\prime}(x)\\\\,dx=f^{\\\\prime}(x)+C \\\\)","\\\\( \\\\int f^{\\\\prime}(x)\\\\,dx=f(x)+C \\\\)","\\\\( \\\\int_a^b f(x)\\\\,dx=f(b)-f(a) \\\\)"]'::jsonb, '2', '[]'::jsonb, NULL, NULL, NULL, '\\( \\int f^{\\prime}(x)\\,dx=f(x)+C \\)。', NULL, NULL, NULL, 2, '["总复习"]'::jsonb, '高等数学（第六版）') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
